from calculator_class import Calculatorcalculator = Calculator()class CalculatorApp:    def __init__(self):        self.calculator = calculator        self.calculator_menu = {            "1.":("ADDITION",self.calculator.Addition),            "2.":("SUBTRACTION",self.calculator.Subtraction),            "3.":("MULTIPLICATION",self.calculator.Multiplication),            "4.":("DIVISION",self.calculator.Division)}        for key, value in self.calculator_menu.items():            print(f"{key}: {value[0]}")